package com.spaceagent.platform.runtime;
import com.spaceagent.platform.runtime.domain.*;import org.junit.jupiter.api.Test;import java.time.Instant;import static org.assertj.core.api.Assertions.*;
class RuntimeGraphSessionDomainTest {private static final Instant NOW=Instant.parse("2026-09-08T00:00:00Z");private static final String HASH="sha256:"+"a".repeat(64);@Test void commandBoundaryIsStableAndConfirmMovesItToCompletedEvidence(){var started=RuntimeGraphSession.start("session","tenant","owner","run",HASH,NOW);var waiting=started.propose("cmd-1",HASH,NOW.plusSeconds(1));assertThat(waiting.state()).isEqualTo(GraphSessionState.WAITING_FOR_COMMAND);var active=waiting.confirm("cmd-1",HASH,NOW.plusSeconds(2));assertThat(active.completedCommandIds()).containsExactly("cmd-1");assertThat(active.cursorSequence()).isEqualTo(1);assertThat(active.revision()).isEqualTo(3);}@Test void mismatchAndUnknownFailClosed(){var waiting=RuntimeGraphSession.start("session","tenant","owner","run",HASH,NOW).propose("cmd-1",HASH,NOW);assertThatThrownBy(()->waiting.confirm("cmd-2",HASH,NOW)).isInstanceOf(IllegalArgumentException.class);var blocked=waiting.blockUnknown(NOW);assertThat(blocked.state()).isEqualTo(GraphSessionState.BLOCKED);assertThat(blocked.blockUnknown(NOW)).isSameAs(blocked);assertThatThrownBy(()->blocked.propose("cmd-2",HASH,NOW)).isInstanceOf(IllegalStateException.class);}}
